hl.bind(mainMod .. " + Z", hl.dsp.exec_cmd("$terminal"))
hl.bind(mainMod .. " + X", hl.dsp.window.close())

-- Launch stuff
hl.bind(mainMod .. " + ALT + C", hl.dsp.exec_cmd("$killPanel; pkill $launcher; $launcher-launch run"))
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.exec_cmd("$killPanel; pkill $launcher; $launcher-launch game"))
hl.bind(mainMod .. " + C", hl.dsp.exec_cmd("$killPanel; pkill $launcher; $launcher-launch drun"))

hl.bind(mainMod .. " + V", hl.dsp.exec_cmd("$killPanel; pkill $launcher || $clipboard | $launcher -dmenu | cliphist decode | wl-copy"))
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd("$killPanel; screenshot output"))
hl.bind(mainMod .. " + ALT + Q", hl.dsp.exec_cmd("screenshot window"))
hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.exec_cmd("screenshot region"))

-- Change window behavior

hl.bind(mainMod .. " + SHIFT + G", hl.dsp.exec_cmd("nk-gamemode"))
hl.bind(mainMod .. " + O", hl.dsp.window.set_prop({ prop = "opaque", value = "toggle", window = "active" }))
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind(mainMod .. " + ALT + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("kill-layers; swaync-client -t"))
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("pkill wlogout || wlogout"))
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd("$killPanel; pkill $launcher || change-navbar-mode"))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("if ! pidof -q navbar-watcher && ! pidof -q navbar-hover; then pkill -SIGUSR1 waybar; fi"))

-- Set wallpaper and waybar skins

hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("customize wallpaper random"))
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd("$killPanel; pkill $launcher || customize"))

hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))
